template <typename AsyncOperation>
bool WaitForAsyncWithTimeout(AsyncOperation const& operation,
                             std::chrono::milliseconds timeout,
                             const wchar_t* label) {
    if (!operation) {
        return false;
    }

    // No Completed delegate is installed: a late provider completion cannot
    // enter this DLL after unload, including when Cancel is ignored.
    auto deadline = std::chrono::steady_clock::now() + timeout;
    auto status = operation.Status();
    while (status == winrt::Windows::Foundation::AsyncStatus::Started &&
           !g_unloading && std::chrono::steady_clock::now() < deadline) {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        status = operation.Status();
    }
    if (status == winrt::Windows::Foundation::AsyncStatus::Completed) {
        return true;
    }

    try {
        operation.Cancel();
    } catch (...) {
    }

    Wh_Log(L"async operation timed out label=%s status=%d timeoutMs=%lld",
           label ? label : L"(unknown)",
           static_cast<int>(status),
           static_cast<long long>(timeout.count()));
    return false;
}

template <typename AsyncOperation>
auto GetAsyncResultWithTimeout(AsyncOperation const& operation,
                               std::chrono::milliseconds timeout,
                               const wchar_t* label)
    -> decltype(operation.GetResults()) {
    if (!WaitForAsyncWithTimeout(operation, timeout, label)) {
        throw winrt::hresult_error(HRESULT_FROM_WIN32(ERROR_TIMEOUT));
    }

    return operation.GetResults();
}

